<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)($_GET['id']??0);if($id===(int)$u['id'])go('profile.php');$q=db()->prepare("SELECT u.id,u.name,p.* FROM users u JOIN student_profiles p ON p.user_id=u.id WHERE u.id=? AND u.status='active'");$q->execute([$id]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Student not found');}$m=match_info((int)$u['id'],$id);$skills=db()->prepare('SELECT s.name FROM user_skills x JOIN skills s ON s.id=x.skill_id WHERE x.user_id=?');$skills->execute([$id]);$subs=db()->prepare('SELECT s.name,x.intent FROM user_subjects x JOIN subjects s ON s.id=x.subject_id WHERE x.user_id=?');$subs->execute([$id]);page_start('Partner profile'); ?><div class="card"><div class="card-body p-4"><div class="d-flex gap-3 align-items-center"><div class="avatar avatar-lg"><?= e(mb_substr($p['name'],0,1)) ?></div><div><h2><?= e($p['name']) ?></h2><p class="text-secondary mb-0"><?= e($p['course']) ?> · Semester <?= e($p['semester']) ?> · <?= e($p['college']) ?></p><div class="match mt-2"><?= $m['score'] ?>% match · ★ <?= e(rating_avg($id)) ?></div></div></div><hr><div class="row"><div class="col-lg-8"><h3 class="h5">About</h3><p><?= nl2br(e($p['about']?:'No introduction added yet.')) ?></p><h3 class="h5 mt-4">Learning goals</h3><p><?= nl2br(e($p['learning_goals']?:'Not added yet.')) ?></p><h3 class="h6">Skills</h3><?php foreach($skills as $x)echo tag($x['name']); ?><h3 class="h6 mt-3">Subjects</h3><?php foreach($subs as $x)echo tag($x['name'].' · '.($x['intent']==='help'?'Can help':'Wants to learn')); ?></div><div class="col-lg-4"><div class="card"><div class="card-body"><h3 class="h6 fw-bold">Why you match</h3><?php if($m['why']):foreach($m['why'] as $w): ?><div class="small py-1"><i class="bi bi-check-circle-fill text-success"></i> <?= e($w) ?></div><?php endforeach;else: ?><p class="small text-secondary">A chance to explore a new learning connection.</p><?php endif ?><hr><div class="small"><strong>Study mode</strong><br><?= e($p['study_mode']?:'Not set') ?><br><strong class="d-block mt-2">Availability</strong><?= e($p['availability_days']?:'Not set') ?> <?= $p['start_time']?' · '.e(substr($p['start_time'],0,5)).'–'.e(substr($p['end_time'],0,5)):'' ?><br><strong class="d-block mt-2">Languages</strong><?= e($p['languages']?:'Not set') ?></div></div></div></div></div><hr><form class="d-inline" method="post" action="../actions/partner-request.php"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="receiver_id" value="<?= $id ?>"><input type="hidden" name="intent" value="send"><button class="btn btn-primary">Send study request</button></form> <a class="btn btn-outline-primary" href="find-partners.php">Back to partners</a> <button class="btn btn-link" data-bs-toggle="collapse" data-bs-target="#report">Report user</button><form id="report" class="collapse mt-3" method="post" action="../actions/report.php"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="reported_id" value="<?= $id ?>"><select class="form-select mb-2" name="reason" required><?php foreach(['Inappropriate behavior','Spam','Fake profile','Harassment','Other'] as $r): ?><option><?= e($r) ?></option><?php endforeach ?></select><textarea class="form-control mb-2" name="description" placeholder="Optional details"></textarea><button class="btn btn-sm btn-outline-danger">Submit report</button></form></div></div><?php page_end(); ?>
